import {getProfile,getProjects,getProject,getImages} from './repository.js?v=profile1';
const $=id=>document.getElementById(id), cats={profile:'PROFILE',web:'WEB REDESIGN',detail:'PRODUCT DETAIL',banner:'BANNER',app:'APP DESIGN'};
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const storage={get(k,f){try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}},set(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{}}};
let state='intro',category=null,position=storage.get('character_position',{x:50,y:48}),nearest=null,target=null,sound=storage.get('sound_enabled',false),audio,hatched=false,routeVersion=0;
position={x:Math.max(6,Math.min(94,Number(position.x)||50)),y:Math.max(8,Math.min(90,Number(position.y)||48))};
const keys=new Set(),escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function beep(freq=660,duration=.07){if(!sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type='square';o.frequency.value=freq;g.gain.setValueAtTime(.025,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration)}catch{}}
function soundUI(){$('sound').setAttribute('aria-pressed',String(sound));$('sound').querySelector('span').textContent=`SOUND ${sound?'ON':'OFF'}`}
$('sound').onclick=()=>{sound=!sound;storage.set('sound_enabled',sound);soundUI();beep()};soundUI();
function hatch(){if(hatched)return;hatched=true;$('egg').classList.add('hidden');$('intro-character').classList.remove('hidden');$('intro-title').textContent='nice to meet you!';$('skip').classList.add('hidden');storage.set('intro_seen',true);beep(880,.16)}
if(storage.get('intro_seen',false)||reduced)hatch();else setTimeout(hatch,2300);

const previews={profile:['gyuyeon','디자이너 소개 · 학력 · 역량'],web:['이월드','웹페이지 리디자인'],detail:['Razer Mouse','오쏘몰 이뮨 비타민'],banner:['삼성 × coyseio','콜라보 배너'],app:['골프존','앱 디자인']};
let returningFromWork=false,reactionTimer,lastGreeting=0;
function react(message,kind='wave'){const player=$('player');player.classList.remove('react-wave','react-happy');clearTimeout(reactionTimer);$('player-reaction').textContent=message;player.classList.add(`react-${kind}`);reactionTimer=setTimeout(()=>{player.classList.remove('react-wave','react-happy');$('player-reaction').textContent=''},1800)}
function showPreview(cat){const box=$('building-preview'),names=previews[cat];box.innerHTML=`<strong>${cats[cat]}</strong>${names.map(n=>`<span>${escapeHtml(n)}</span>`).join('')}<small>클릭해서 이동</small>`;const p=positions[cat];box.style.left=`${Math.max(22,Math.min(78,p.x))}%`;box.style.top=`${Math.max(4,p.y-28)}%`;box.hidden=false;document.querySelectorAll('[data-cat]').forEach(b=>b.classList.toggle('preview-active',b.dataset.cat===cat))}
function hidePreview(){$('building-preview').hidden=true;document.querySelectorAll('.preview-active').forEach(b=>b.classList.remove('preview-active'))}

let swingAnimation;
$('chain-hit').onclick=e=>{e.stopPropagation();if(state!=='intro')return;beep(300,.04);swingAnimation?.cancel();if(reduced)return;swingAnimation=$('toy').animate([{transform:'rotate(0deg)'},{transform:'rotate(12deg)',offset:.12},{transform:'rotate(-9deg)',offset:.28},{transform:'rotate(6deg)',offset:.45},{transform:'rotate(-4deg)',offset:.61},{transform:'rotate(2deg)',offset:.76},{transform:'rotate(-.8deg)',offset:.9},{transform:'rotate(0deg)'}],{duration:1900,easing:'ease-in-out'});};
async function enterPortal(version){
  swingAnimation?.cancel();if(reduced)return;
  const toy=$('toy'),rect=toy.getBoundingClientRect(),header=document.querySelector('.site-header').getBoundingClientRect().bottom;
  const overlay=document.createElement('div');overlay.className='portal-overlay';overlay.style.top=`${header}px`;overlay.setAttribute('aria-hidden','true');
  const clone=toy.cloneNode(true);clone.querySelectorAll('[id]').forEach(n=>n.removeAttribute('id'));clone.removeAttribute('id');clone.classList.add('portal-clone');clone.style.cssText=`left:${rect.left}px;top:${rect.top-header}px;width:${rect.width}px;height:${rect.height}px;aspect-ratio:auto;transform-origin:50% 58%;`;overlay.append(clone);document.body.append(overlay);
  const screen=toy.querySelector('.screen').getBoundingClientRect(),dx=innerWidth/2-(screen.left+screen.width/2),dy=header+(innerHeight-header-105)/2-(screen.top+screen.height/2),scale=Math.max((innerWidth*.9)/screen.width,(innerHeight-header-140)/screen.height);
  const animation=clone.animate([{transform:'translate(0,0) scale(1)',filter:'blur(0px)'},{transform:`translate(${dx*.15}px,${dy*.15}px) scale(1.12)`,filter:'blur(0px)',offset:.23},{transform:`translate(${dx}px,${dy}px) scale(${scale})`,filter:'blur(2px)'}],{duration:760,easing:'cubic-bezier(.64,0,.25,1)',fill:'forwards'});
  try{await animation.finished}catch{};if(version!==routeVersion){overlay.remove();return;}return overlay;
}
$('skip').onclick=hatch;$('play').onclick=()=>{hatch();location.hash='/map'};
$('toy').onclick=e=>{if(state==='intro'&&!e.target.closest('button,a')){hatch();location.hash='/map'}};
function showStage(playing){$('stage').classList.remove('hidden');$('project').classList.add('hidden');$('stage').classList.toggle('playing',playing);document.body.classList.toggle('game-mode',playing);$('intro').classList.toggle('hidden',playing);$('under-label').textContent=playing?'MOVE · EXPLORE · MAKE YOURSELF AT HOME':'';window.scrollTo(0,0)}
function map(){const celebrate=returningFromWork;returningFromWork=false;state='map';target=null;showStage(true);$('panel').classList.add('hidden');$('map').classList.remove('hidden');paint();if(celebrate)react('다음 작업도 만나봐요!','happy');}
function panel(content){state='panel';target=null;showStage(true);$('map').classList.add('hidden');$('panel').classList.remove('hidden');$('panel').innerHTML=content;$('panel').scrollTop=0;bindImages($('panel'));$('panel').querySelector('[data-map]')?.addEventListener('click',()=>location.hash='/map')}
function panelHeader(title){return `<div class="panel-top"><h2>${title}</h2><button class="pixel-button" data-map>BACK</button></div>`}
async function showCategory(cat,version){returningFromWork=true;hidePreview();category=cat;storage.set('last_category',cat);panel(panelHeader(cats[cat])+'<p class="sample-note" role="status">불러오는 중…</p>');
if(cat==='profile'){const p=await getProfile();if(version!==routeVersion)return;panel(panelHeader('PROFILE')+`<div class="profile-card"><img src="${escapeHtml(p.avatar_url)}" alt="gyuyeon 캐릭터"><div><h3>${escapeHtml(p.name)}</h3><p>${escapeHtml(p.job_title)}</p></div></div><div class="profile-section"><h4>INFORMATION</h4><dl class="profile-info"><div><dt>AGE</dt><dd>${escapeHtml(p.birth_date)}</dd></div><div><dt>PHONE NUMBER</dt><dd><a href="tel:${escapeHtml(p.phone)}">${escapeHtml(p.phone)}</a></dd></div><div><dt>EMAIL</dt><dd><a href="mailto:${escapeHtml(p.email)}">${escapeHtml(p.email)}</a></dd></div></dl></div><div class="profile-section"><h4>ACADEMY</h4><div class="education-list">${p.education.map(e=>`<div><span>${escapeHtml(e.period)}</span><p>${escapeHtml(e.description)}</p></div>`).join('')}</div></div><div class="profile-section"><h4>TECHNICAL SKILLS</h4><div class="tags">${p.skills.map(t=>`<span>${escapeHtml(t)}</span>`).join('')}</div></div><div class="profile-section"><h4>TOOLS</h4><div class="tags">${p.tools.map(t=>`<span>${escapeHtml(t)}</span>`).join('')}</div></div>`);
}else{const projects=await getProjects(cat);if(version!==routeVersion)return;panel(panelHeader(cats[cat])+`<p class="sample-note">교체 가능한 샘플 작업입니다.</p><div class="cards">${projects.map(p=>`<a class="project-card" href="#/project/${encodeURIComponent(p.slug)}"><img src="${escapeHtml(p.thumbnail_url)}" alt="${escapeHtml(p.title)} 샘플 디자인" loading="lazy"><h3>${escapeHtml(p.title)}</h3><p>${escapeHtml(p.summary)}</p><span class="year">${escapeHtml(p.year)}</span></a>`).join('')}</div>${projects.length?'':'<p class="empty">작업물을 준비하고 있어요.</p>'}`)}}
function imageMarkup(src,alt,caption=''){return `<figure class="image-wrap"><div class="image-loading" role="status">이미지 불러오는 중…</div><img src="${escapeHtml(src)}" alt="${escapeHtml(alt)}" loading="lazy">${caption?`<figcaption>${escapeHtml(caption)}</figcaption>`:''}</figure>`}
function bindImages(root){root.querySelectorAll('img').forEach(img=>{const loading=img.previousElementSibling?.classList.contains('image-loading')?img.previousElementSibling:null;const ok=()=>loading?.remove();const fail=()=>{if(loading){loading.textContent='이미지를 불러오지 못했어요. 잠시 후 다시 방문해 주세요.';img.hidden=true}else{img.alt='이미지를 불러오지 못했어요.';img.style.minHeight='70px'}};img.addEventListener('load',ok,{once:true});img.addEventListener('error',fail,{once:true});if(img.complete){img.naturalWidth?ok():fail()}})}
async function showProject(slug,version){state='project';document.body.classList.remove('game-mode');target=null;$('stage').classList.add('hidden');$('project').classList.remove('hidden');$('project').innerHTML='<p role="status">작업을 불러오는 중…</p>';window.scrollTo(0,0);const p=await getProject(slug);if(version!==routeVersion)return;if(!p){$('project').innerHTML='<h1>작업을 찾을 수 없어요.</h1><a class="project-back" href="#/map">마을로 돌아가기</a>';return;}category=p.category;const images=await getImages(p.id);if(version!==routeVersion)return;
$('project').innerHTML=`<div class="project-nav"><button id="list-back">BACK TO ${cats[p.category]}</button><span>GYUYEON / SAMPLE PROJECT</span></div><h1>${escapeHtml(p.title)}</h1><p class="project-summary">${escapeHtml(p.summary)}</p>${imageMarkup(p.cover_url,p.title+' 대표 샘플 디자인')}<div class="project-overview"><div><h2>프로젝트 개요</h2><p>${escapeHtml(p.overview)}</p></div><dl class="project-meta"><div><dt>PERIOD</dt><dd>${escapeHtml(p.period)}</dd></div><div><dt>ROLE</dt><dd>${escapeHtml(p.role)}</dd></div><div><dt>TOOLS</dt><dd>${p.tools.map(escapeHtml).join(' / ')}</dd></div><div><dt>CATEGORY</dt><dd>${cats[p.category]}</dd></div></dl></div><div class="concept"><h2>기획 의도와 디자인 방향</h2><p>${escapeHtml(p.design_concept)}</p></div>${images.map(i=>imageMarkup(i.image_url,i.alt_text,i.caption)).join('')}<div class="project-bottom"><button class="project-back" id="bottom-back">작업 목록으로 돌아가기</button><span>THANK YOU FOR PLAYING</span></div>`;
if(p.external_url&&/^https?:\/\//.test(p.external_url)){const link=document.createElement('a');link.href=p.external_url;link.target='_blank';link.rel='noopener noreferrer';link.textContent='관련 사이트 보기';link.className='project-back';$('project').append(link)}
$('list-back').onclick=$('bottom-back').onclick=()=>location.hash=`/category/${p.category}`;bindImages($('project'));document.title=`${p.title} — gyuyeon`;}
async function route(){const version=++routeVersion;keys.clear();target=null;document.title='gyuyeon — interactive portfolio';const parts=location.hash.replace(/^#\/?/,'').split('/');let portal;if(state==='intro'&&['map','menu','category'].includes(parts[0])){state='transition';portal=await enterPortal(version);if(version!==routeVersion)return;}try{if(parts[0]==='project')await showProject(decodeURIComponent(parts[1]||''),version);else if(parts[0]==='category'&&cats[parts[1]])await showCategory(parts[1],version);else if(parts[0]==='menu'){panel(panelHeader('CHOOSE YOUR WORLD')+`<div class="menu-list">${Object.entries(cats).map(([k,v])=>`<button data-category="${k}">${v}</button>`).join('')}</div>`);$('panel').querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>location.hash=`/category/${b.dataset.category}`)}else if(parts[0]==='map'){map()}else{state='intro';showStage(false);$('panel').classList.add('hidden');$('map').classList.add('hidden')}}catch{if(version!==routeVersion)return;const message='<p class="empty">콘텐츠를 불러오지 못했어요.<br>새로고침하여 다시 시도해 주세요.</p>';if(state==='project')$('project').innerHTML=message+'<a href="#/map">마을로 돌아가기</a>';else panel(panelHeader('잠시 기다려 주세요')+message)}finally{if(portal){portal.animate([{opacity:1},{opacity:0}],{duration:180,fill:'forwards'}).finished.finally(()=>portal.remove());}}}
window.addEventListener('hashchange',route);route();$('menu').onclick=()=>location.hash='/menu';$('device-menu').onclick=()=>{hatch();beep();location.hash='/menu'};
function back(){beep(440);if(state==='project')location.hash=`/category/${category||'web'}`;else if(state==='panel')location.hash='/map';else if(state==='map')location.hash='/';}
function open(){if(state==='intro')$('play').click();else if(state==='map'&&nearest){beep();location.hash=`/category/${nearest}`}}
$('back').onclick=back;$('open').onclick=open;
const positions={profile:{x:51,y:55},web:{x:65,y:34},detail:{x:36,y:75},banner:{x:34,y:34},app:{x:71,y:77}};
function travelTo(cat){if(state!=='map')return;target={...positions[cat],cat};keys.clear();beep();if(reduced){position={x:target.x,y:target.y};paint();target=null;location.hash=`/category/${cat}`}}
document.querySelectorAll('.place,.building-hit').forEach(b=>{b.onclick=()=>{hidePreview();travelTo(b.dataset.cat)};b.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse')showPreview(b.dataset.cat)});b.addEventListener('pointerleave',hidePreview);b.addEventListener('focus',()=>showPreview(b.dataset.cat));b.addEventListener('blur',hidePreview)});
function paint(){const player=$('player');player.style.left=`${position.x}%`;player.style.top=`${position.y}%`;let distance=Infinity;nearest=null;Object.entries(positions).forEach(([cat,p])=>{const d=Math.hypot(position.x-p.x,position.y-p.y);if(d<distance){distance=d;nearest=cat}});if(distance>18)nearest=null;if(nearest&&distance<8&&!target&&performance.now()-lastGreeting>6000){lastGreeting=performance.now();react('안녕! Enter로 열어봐요.');}document.querySelectorAll('.place').forEach(b=>b.classList.toggle('near',b.dataset.cat===nearest));$('map-hint').textContent=nearest?`${cats[nearest]} · ENTER TO OPEN`:'방향키로 이동하거나 건물을 클릭해 보세요';storage.set('character_position',position)}
const directions={ArrowUp:'up',w:'up',W:'up',ArrowDown:'down',s:'down',S:'down',ArrowLeft:'left',a:'left',A:'left',ArrowRight:'right',d:'right',D:'right'};
window.addEventListener('keydown',e=>{if(e.target.closest('input,textarea,select'))return;const dir=directions[e.key];if(state==='map'&&dir){e.preventDefault();keys.add(dir);target=null;}else if((e.key==='Enter'||e.key===' ')&&['map','intro'].includes(state)&&!e.target.closest('button,a')){e.preventDefault();if(!e.repeat)open()}else if(e.key==='Escape'){e.preventDefault();back()}});
window.addEventListener('keyup',e=>keys.delete(directions[e.key]));window.addEventListener('blur',()=>keys.clear());document.addEventListener('visibilitychange',()=>keys.clear());
document.querySelectorAll('[data-dir]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();if(state!=='map')return;b.setPointerCapture(e.pointerId);keys.add(b.dataset.dir);target=null;beep(330,.03)});for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,()=>keys.delete(b.dataset.dir));});
let previous=performance.now(),lastSaved=0;function tick(time){const dt=Math.min((time-previous)/1000,.04);previous=time;if(state==='map'){let dx=Number(keys.has('right'))-Number(keys.has('left')),dy=Number(keys.has('down'))-Number(keys.has('up'));if(target){dx=target.x-position.x;dy=target.y-position.y;if(Math.hypot(dx,dy)<1.4){const cat=target.cat;target=null;location.hash=`/category/${cat}`;dx=dy=0;}}
const moving=dx!==0||dy!==0;$('player').classList.toggle('walking',moving);if(moving){const length=Math.hypot(dx,dy);position.x=Math.max(6,Math.min(94,position.x+dx/length*dt*(target?80:48)));position.y=Math.max(10,Math.min(90,position.y+dy/length*dt*(target?100:60)));$('player').style.left=`${position.x}%`;$('player').style.top=`${position.y}%`;if(time-lastSaved>110){paint();lastSaved=time}}}requestAnimationFrame(tick)}requestAnimationFrame(tick);
bindImages(document);

const islandArt=$('island-art');function mapArtReady(){if(islandArt.naturalWidth)islandArt.classList.add('loaded');}islandArt.addEventListener('load',mapArtReady);islandArt.addEventListener('error',()=>{const note=islandArt.nextElementSibling;note.textContent='지도를 불러오지 못했어요. 새로고침해 주세요.';});if(islandArt.complete)mapArtReady();
